(6589940, 982704, 10848, '<td valign="top">The show of motion is an interesting concept, expecially in what looks like an airport lobby? The pattern of the floor is perfect for the angles.</td>', 'The show of motion is an interesting concept, expecially in what looks like an airport lobby? The pattern of the floor is perfect for the angles.', '2011-11-08 22:48:59.000000', NULL, 1),
(6589942, 982731, 10848, '<td valign="top">Simply beautiful! Great lighting and composition. The color combinations make this image really pop. Good luck!</td>', 'Simply beautiful! Great lighting and composition. The color combinations make this image really pop. Good luck!', '2011-11-08 22:50:01.000000', NULL, 1),
