INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6592872, 982815, 104230, '<td valign="top">This is fun and a creative take on the challenge topis, but it seems rather flat.  I wish you could have captured it in more interesting light, or processed it in some way to make it more interesting.. possibly more abstract (but then that is my bias for what to do with interesting shapes).</td>', 'This is fun and a creative take on the challenge topis, but it seems rather flat.  I wish you could have captured it in more interesting light, or processed it in some way to make it more interesting.. possibly more abstract (but then that is my bias for what to do with interesting shapes).', '2011-11-12 11:39:27.000000', NULL, 1),
(6592875, 982718, 104230, '<td valign="top">Nice, I like how the checkered pattern on the umbrella breaks up the repetition. I find the branches and leaves a bit distracting, especially with the brightness of the yellow, but I realize with that POV you probably couldn''t include the umbrella without them being in the frame.</td>', 'Nice, I like how the checkered pattern on the umbrella breaks up the repetition. I find the branches and leaves a bit distracting, especially with the brightness of the yellow, but I realize with that POV you probably couldn''t include the umbrella without them being in the frame.', '2011-11-12 11:44:39.000000', NULL, 1),
(6592877, 982573, 104230, '<td valign="top">I love the mood and colors here, but I''m not sure the picture''s strength relies much on "right angles".</td>', 'I love the mood and colors here, but I''m not sure the picture''s strength relies much on "right angles".', '2011-11-12 11:47:25.000000', NULL, 1),
(6592881, 982575, 118154, '<td valign="top">Nice image.</td>', 'Nice image.', '2011-11-12 11:52:40.000000', NULL, 1),
